BEGIN;

-- Generated by pinned Prisma 7.10.0 schema-to-schema diff; reviewed as additive.
CREATE TYPE "CommunityVisibility" AS ENUM ('PUBLIC', 'PRIVATE');
CREATE TYPE "MembershipStatus" AS ENUM ('PENDING', 'MEMBER');

CREATE TABLE "Community" (
    "id" UUID NOT NULL,
    "ownerId" UUID NOT NULL,
    "name" VARCHAR(80) NOT NULL,
    "description" VARCHAR(1000) NOT NULL,
    "visibility" "CommunityVisibility" NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Community_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "CommunityMembership" (
    "communityId" UUID NOT NULL,
    "userId" UUID NOT NULL,
    "status" "MembershipStatus" NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CommunityMembership_pkey" PRIMARY KEY ("communityId","userId")
);
CREATE INDEX "Community_createdAt_id_idx" ON "Community"("createdAt", "id");
CREATE INDEX "CommunityMembership_userId_status_idx" ON "CommunityMembership"("userId", "status");
ALTER TABLE "Community" ADD CONSTRAINT "Community_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "CommunityMembership" ADD CONSTRAINT "CommunityMembership_communityId_fkey" FOREIGN KEY ("communityId") REFERENCES "Community"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "CommunityMembership" ADD CONSTRAINT "CommunityMembership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- Custom text checks supplement the generated column bounds. Unicode lengths
-- use PostgreSQL code points, as the TypeScript boundary does, not UTF-16 units.
ALTER TABLE "Community" ADD CONSTRAINT "Community_text_policy" CHECK (
    char_length(name) BETWEEN 1 AND 80 AND name ~ '[^[:space:]]'
    AND name !~ '[[:cntrl:]]'
    AND char_length(description) <= 1000
);

COMMIT;
